styles.container:
max-width: 740px; margin: 0 auto; padding: 20px; font-family: 
    "Helvetica Neue", Helvetica, Arial, "PingFang SC", "Hiragino Sans GB",
    "Microsoft YaHei", sans-serif; font-size: 16px; line-height: 1.8 !important; color: #3f3f3f !important; background-color: #ffffff; word-wrap: break-word;

styles.h1:
font-size: 28px;
line-height: 1.4;
font-weight: 700;
color: #111111;
position: relative;
padding-bottom: 16px;
border-bottom: 2px solid #ff6a00;
margin: 32px 0 24px;
letter-spacing: 0.5px;

styles.h2:
display: table;
padding: 0.6em 1.5em;
margin: 2.8em auto 1.5em;
font-size: 1.3em;
font-weight: 700;
text-align: center;
color: #fff;
background: linear-gradient(135deg, #ff6a00, #ff8c00);
border-radius: 30px;
position: relative;
box-shadow: 0 6px 16px rgba(255, 106, 0, 0.25);
letter-spacing: 0.03em;
border: 2px solid rgba(255, 255, 255, 0.3);
z-index: 1;
transition: all 0.3s ease;

styles.h3:
font-size: 1.2em;
font-weight: 600;
color: #333;
margin: 2.2em 0 1em;
padding-left: 16px;
border-left: 4px solid #ff8c00;
line-height: 1.5;
position: relative;

styles.a:
font-family: 
    "Helvetica Neue", Helvetica, Arial, "PingFang SC", "Hiragino Sans GB",
    "Microsoft YaHei", sans-serif; color: #ff6a00; text-decoration: none; font-weight: 600; border-bottom: 2px solid rgba(255, 106, 0, 0.3); padding: 0 2px; transition: all 0.3s ease;

